    val i2cAddr = 0x76
    val i2cReg = 0x00
    val i2cLen = 4

    println("I2C read from allowed address 0x${i2cAddr.toString(16)}")
    val i2cData = I2C.read(i2cAddr, i2cReg, i2cLen)
