    try {
        println("Attempting forbidden I2C address 0x${forbiddenAddr.toString(16)}...")
        I2C.read(forbiddenAddr, 0x00, 4)
        println("ERROR: Should not reach here - address 0x${forbiddenAddr.toString(16)} is forbidden!")
    } catch (e: Exception) {
        println("Caught exception for forbidden address, self-repairing to 0x${i2cAddr.toString(16)}")
        I2C.read(i2cAddr, 0x00, 4)
    }

    // Modbus operations - strictly on registers 100..200
    val plcHost = "192.168.1.100"
    val allowedReg = 150

    println("Modbus read from allowed register $allowedReg")
    val modbusValue = PLC.modbusRead(plcHost, allowedReg)
    println("Modbus read value: $modbusValue")

    // Attempt forbidden Modbus register - self-repair
    val forbiddenReg = 50
    try {
        println("Attempting forbidden Modbus register $forbiddenReg...")
        PLC.modbusRead(plcHost, forbiddenReg)
        println("ERROR: Should not reach here - register $forbiddenReg is forbidden!")
    } catch (e: Exception) {
        println("Caught exception for forbidden register, self-repairing to $allowedReg")
        PLC.modbusRead(plcHost, allowedReg)
    }

    // Write to allowed Modbus register
    println("Modbus write to allowed register $allowedReg")
    val writeSuccess = PLC.modbusWrite(plcHost, allowedReg, 42)
